class Solution {
    public boolean isPalindrome(ListNode head) {
        if (head == null || head.next == null) {
            return true;
        }

        ListNode firstHalfEnd = endOfFirstHalf(head);
        ListNode secondHalfStart = reverse(firstHalfEnd.next);

        boolean palindrome = true;
        ListNode p1 = head;
        ListNode p2 = secondHalfStart;
        while (palindrome && p2 != null) {
            if (p1.val != p2.val) {
                palindrome = false;
            }
            p1 = p1.next;
            p2 = p2.next;
        }

        firstHalfEnd.next = reverse(secondHalfStart);
        return palindrome;
    }

    private ListNode endOfFirstHalf(ListNode head) {
        ListNode slow = head;
        ListNode fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

    private ListNode reverse(ListNode head) {
        ListNode prev = null;
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}

import java.util.*;

class Solution {
    public boolean isPalindrome(ListNode head) {
        Deque<Integer> firstHalf = new ArrayDeque<>();
        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            firstHalf.push(slow.val);
            slow = slow.next;
            fast = fast.next.next;
        }

        if (fast != null) {
            slow = slow.next;
        }

        while (slow != null) {
            if (firstHalf.pop().intValue() != slow.val) {
                return false;
            }
            slow = slow.next;
        }
        return true;
    }
}

class Solution {
    private ListNode front;

    public boolean isPalindrome(ListNode head) {
        front = head;
        return check(head);
    }

    private boolean check(ListNode right) {
        if (right == null) {
            return true;
        }
        if (!check(right.next)) {
            return false;
        }
        boolean same = front.val == right.val;
        front = front.next;
        return same;
    }
}

import java.util.*;

class Solution {
    public boolean isPalindrome(ListNode head) {
        List<Integer> values = new ArrayList<>();
        ListNode curr = head;
        while (curr != null) {
            values.add(curr.val);
            curr = curr.next;
        }

        int left = 0;
        int right = values.size() - 1;
        while (left < right) {
            if (!values.get(left).equals(values.get(right))) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}
